Object.assign(state,{mode:'overview',aiEvent:-1,provider:'all',merge:0,mergeGoal:0,mergePlaying:false,orbiting:false,exploring:false,viewTween:null,hoverAI:-1,pointer:[0,0],zoomIntent:0,zoomTarget:null,paused:false});
const providerOrder=['OpenAI','Anthropic','Google','DeepSeek','Qwen'];
const providerColors={OpenAI:[.49,.89,.79],Anthropic:[1,.65,.37],Google:[.52,.67,1],DeepSeek:[.36,.81,1],Qwen:[.77,.51,1]};
const galaxyFrames=[{origin:[0,0,0],matrix:[1,0,0,0,1,0,0,0,1],scale:1},{origin:[222,45,-145],matrix:[1,0,0,0,1,0,0,0,1],scale:.81}];
