function syncOrbit(v,resetBase=true){const d=sub(v.cam,v.target),r=len(d);orbit.center=v.target.slice();orbit.goalCenter=v.target.slice();orbit.yaw=orbit.goalYaw=Math.atan2(d[0],d[2]);orbit.pitch=orbit.goalPitch=Math.asin(clamp(d[1]/r,-1,1));orbit.radius=orbit.goalRadius=r;orbit.velocity=[0,0];if(resetBase)orbit.zoomBase=r;}
