function startTransit(v,index,event=-1){const start=state.cam.slice(),d=sub(v.cam,start),dist=len(d),side=norm(cross(norm(d),[0,1,0])),lift=Math.min(40,7+dist*.065);const cp1=add(add(lerp(start,v.cam,.24),[0,lift,0]),mul(side,Math.min(19,dist*.06))),cp2=add(lerp(start,v.cam,.77),[0,lift*.55,0]);
 state.viewTween=null;state.from=state.active;state.zoomIntent=0;state.zoomTarget=null;state.dwell=0;state.idle=0;state.orbiting=false;state.hoveredStar=-1;state.hoverAI=-1;state.flight={index,event,start,end:v.cam,startT:state.target.slice(),endT:v.target,startFov:state.fov,endFov:v.fov,cp1,cp2,t:0,duration:state.reduced?.25:clamp(2.2+dist*.005,2.3,4.8),queued:null,sign:1};
 const f=state.flight;f.arc=makeArc(f);f.startDir=norm(sub(f.startT,start));f.endDir=norm(sub(v.target,v.cam));f.lookStart=len(sub(f.startT,start));f.lookEnd=len(sub(v.target,v.cam));hideReading();$('aiIntro').hidden=true;document.body.classList.add('flying');$('flightControls').hidden=false;$('flightText').style.opacity=state.reduced?'0':'';playFlightSound();
}
function navigate(i,opts={}){if(!state.ready)return;i=clamp(Math.round(i),-1,profile.chapters.length-1);if(i<0){showWorld('overview');return;}if(state.flight)finishFlight();if(i===state.active&&state.mode==='chapter'&&!opts.replay){animateView(targetView(i));return;}state.mode='chapter';state.aiEvent=-1;startTransit(targetView(i),i);$('flightTitle').textContent='飞往 · '+profile.chapters[i].label;$('flightSubtitle').textContent=profile.chapters[i].transition;$('flightCode').textContent='YOUR GALAXY / FOLLOW THE LIGHT';}
