function renderEvent(i){const e=profile.ai_history[i];$('eventReader').hidden=false;$('eventMeta').textContent=e.provider+' / '+e.date+' / '+(e.kind==='product'?'产品与工具事件':'模型发布');$('eventTitle').textContent=e.name;$('eventHeadline').textContent=e.title;$('eventSummary').textContent=e.summary;const u=safePublicURL(e.url);$('eventSource').hidden=!u;if(u)$('eventSource').href=u;$('eventSource').textContent=defaultEvent(e)?'阅读官方发布 ↗':'查看导入文件提供的来源 ↗';document.documentElement.style.setProperty('--accent','rgb('+providerColors[e.provider].map(x=>Math.round(x*255)).join(',')+')');$('prevEvent').disabled=i===0;$('nextEvent').disabled=i===profile.ai_history.length-1;}
