 const cs=state.mode==='chapter'&&!hide&&state.active>=0,cp=cs?project(companionWorld()):null;$('companionLabel').hidden=!cp||cp.x<15||cp.x>state.w-30||cp.y<88||cp.y>state.h-130;if(!$('companionLabel').hidden){$('companionLabel').style.left=cp.x+'px';$('companionLabel').style.top=cp.y+'px';$('companionLabel').classList.toggle('left',cp.x>state.w-230);}
