 $('focusHint').hidden=!ht||!isMap||hide;if(!$('focusHint').hidden){$('focusName').textContent=ht.name;$('focusHint').style.left=clamp(state.pointer[0]+20,20,state.w-240)+'px';$('focusHint').style.top=clamp(state.pointer[1]+25,105,state.h-220)+'px';$('focusHint').style.setProperty('--lock',clamp(state.zoomIntent/350));}
