function resize(){const was=state.ready;state.w=innerWidth;state.h=innerHeight;resizeBuffers();updateWorld();cacheTopicPositions();if(!state.flight){const v=state.mode==='chapter'?targetView(state.active):state.mode==='event'?eventView(state.aiEvent):modeView(state.mode);state.cam=v.cam;state.target=v.target;state.fov=v.fov;syncOrbit(v);state.viewTween=null;}if(was)paint();}
function paint(){basis();renderGL();drawOverlay();updateLabels();updateReadCue();}
function tick(dt,draw=true){dt=Math.min(Math.max(dt,0),.1);state.delta=dt;if(!state.reduced&&!state.paused)state.time+=dt;
 advanceEncounter(dt);updateWorld();
 if(!document.activeElement||document.activeElement.id!=='encounterRange')$('encounterRange').value=Math.round(state.merge*100);
 $('encounterRange').setAttribute('aria-valuetext',$('encounterCaption').textContent);
 if(state.flight){const f=state.flight;f.t=clamp(f.t+dt/f.duration);const t=f.t,e=smoother(t),u=arcT(f.arc,e);state.cam=state.reduced?lerp(f.start,f.end,e):bezier(f.start,f.cp1,f.cp2,f.end,u);const dir=slerpDir(f.startDir,f.endDir,e);state.target=add(state.cam,mul(dir,mix(f.lookStart,f.lookEnd,e)));state.fov=mix(f.startFov,f.endFov,e)+(state.reduced?0:3.5*16*t*t*(1-t)*(1-t));state.bank=0;if(t>=1)finishFlight();}
 else if(state.viewTween){const t=state.viewTween;t.t=clamp(t.t+dt/t.duration);const e=smoother(t.t);state.cam=lerp(t.startCam,t.end.cam,e);state.target=lerp(t.startT,t.end.target,e);state.fov=mix(t.startFov,t.end.fov,e);if(t.t>=1){syncOrbit(t.end);state.viewTween=null;}}
 else{state.idle+=dt;if(state.orbiting&&!state.reduced)orbit.goalYaw+=dt*.09;const a=1-Math.exp(-dt*8);orbit.yaw=mix(orbit.yaw,orbit.goalYaw,a);orbit.pitch=mix(orbit.pitch,orbit.goalPitch,a);orbit.radius=mix(orbit.radius,orbit.goalRadius,a);orbit.center=lerp(orbit.center,orbit.goalCenter,a);state.target=orbit.center.slice();state.cam=add(orbit.center,[Math.sin(orbit.yaw)*Math.cos(orbit.pitch)*orbit.radius,Math.sin(orbit.pitch)*orbit.radius,Math.cos(orbit.yaw)*Math.cos(orbit.pitch)*orbit.radius]);state.bank=0;
 if(state.auto&&state.mode==='chapter'&&!state.hover&&!state.focus&&!document.querySelector('dialog[open]')){state.dwell+=dt;if(state.dwell>=45)navigate(state.active===profile.chapters.length-1?-1:state.active+1);}}
 if(draw){paint();if(state.monitor&&state.frame%15===0)$('performance').textContent=Math.round(1000/state.frameEMA)+' FPS · '+canvas.width+' × '+canvas.height+' · '+Math.round(orbit.radius)+' u · '+(state.gl?'WebGL':'静态回退');}state.frame++;
}
function interruptCamera(){if(state.flight||state.encounterCinematic)return false;if(state.viewTween){state.viewTween=null;syncOrbit({cam:state.cam,target:state.target,fov:state.fov},false);}state.orbiting=false;if(state.auto)setAuto(false);$('orbitToggle').setAttribute('aria-pressed','false');if(['overview','personal','ai'].includes(state.mode)){state.exploring=true;document.body.classList.add('exploring');}return true;}
function findHit(x,y,limit=42){let best=null;const consider=(p,type,i)=>{const q=project(p);if(!q)return;const d=Math.hypot(q.x-x,q.y-y);if(d<limit&&(!best||d<best.d))best={type,i,d,p};};if(state.mode!=='ai')nodes.forEach((p,i)=>consider(p,'person',i));if(state.mode!=='personal')aiNodes.forEach((p,i)=>{if(state.provider==='all'||profile.ai_history[i].provider===state.provider)consider(p,'ai',i);});return best;}
function goHit(hit){if(!hit)return;hit.type==='person'?navigate(hit.i):navigateAI(hit.i);}
function dolly(amount,x=state.w*.6,y=state.h*.45,lock=true){if(!interruptCamera())return;const hit=['overview','personal','ai'].includes(state.mode)?findHit(x,y,70):null;
 if(hit&&amount<0&&lock){const key=hit.type+hit.i;if(state.zoomTarget!==key){state.zoomTarget=key;state.zoomIntent=0;}state.zoomIntent+=Math.abs(amount);orbit.goalCenter=lerp(orbit.goalCenter,hit.p,.14);if(state.zoomIntent>350){state.zoomIntent=0;goHit(hit);return;}}
 else if(amount>0){state.zoomIntent=0;state.zoomTarget=null;}
 orbit.goalRadius=clamp(orbit.goalRadius*Math.exp(clamp(amount,-240,240)*.0019),cameraMin,cameraMax);if(state.mode==='chapter'&&orbit.goalRadius>230)showWorld('personal');if(state.mode==='event'&&orbit.goalRadius>230)showWorld('ai');}
function pan(dx,dy){const scale=2*orbit.radius*Math.tan(state.fov*Math.PI/360)/state.h,move=add(mul(R,-dx*scale),mul(U,dy*scale));orbit.goalCenter=add(orbit.goalCenter,move).map(x=>clamp(x,-1800,1800));}
function pointerMetric(){const a=[...activePointers.values()];if(a.length<2)return null;return {x:(a[0].x+a[1].x)/2,y:(a[0].y+a[1].y)/2,d:Math.max(1,Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y))};}
canvas.addEventListener('contextmenu',e=>e.preventDefault());
canvas.addEventListener('pointerdown',e=>{if(!interruptCamera())return;activePointers.set(e.pointerId,{x:e.clientX,y:e.clientY});canvas.setPointerCapture(e.pointerId);gesture={x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,pan:e.button===2||e.shiftKey,metric:pointerMetric(),moved:false};canvas.style.cursor='grabbing';});
canvas.addEventListener('pointermove',e=>{state.pointer=[e.clientX,e.clientY];if(!activePointers.has(e.pointerId)){if(['overview','personal','ai'].includes(state.mode)){const hit=findHit(e.clientX,e.clientY);state.hoveredStar=hit?.type==='person'?hit.i:-1;state.hoverAI=hit?.type==='ai'?hit.i:-1;canvas.style.cursor=hit?'pointer':'grab';}return;}
 const old=activePointers.get(e.pointerId);activePointers.set(e.pointerId,{x:e.clientX,y:e.clientY});const metric=pointerMetric();if(metric&&gesture.metric){const prev=gesture.metric;orbit.goalRadius=clamp(orbit.goalRadius*prev.d/metric.d,cameraMin,cameraMax);pan(metric.x-prev.x,metric.y-prev.y);gesture.metric=metric;gesture.moved=true;}
 else if(!metric){const dx=e.clientX-old.x,dy=e.clientY-old.y;if(e.shiftKey||gesture.pan)pan(dx,dy);else{orbit.goalYaw-=dx*.005;orbit.goalPitch=clamp(orbit.goalPitch+dy*.004,-.25,1.48);}gesture.moved=gesture.moved||Math.hypot(e.clientX-gesture.startX,e.clientY-gesture.startY)>5;}
 else gesture.metric=metric;
});
function releasePointer(e){activePointers.delete(e.pointerId);if(!activePointers.size){gesture=null;canvas.style.cursor='grab';}else if(gesture)gesture.metric=pointerMetric();}
canvas.addEventListener('pointerup',releasePointer);canvas.addEventListener('pointercancel',releasePointer);canvas.addEventListener('lostpointercapture',e=>{if(activePointers.has(e.pointerId))releasePointer(e);});
canvas.addEventListener('dblclick',e=>{if(state.flight)return;goHit(findHit(e.clientX,e.clientY,100));});
window.addEventListener('pointermove',e=>{state.pointer=[e.clientX,e.clientY];});
window.addEventListener('wheel',e=>{if(document.querySelector('dialog[open]')||e.target.closest('.reader,.event-reader,.ai-intro,.companion-card,.footer,.header,.encounter-panel'))return;e.preventDefault();let d=e.deltaY*(e.deltaMode===1?16:e.deltaMode===2?state.h:1);if(e.ctrlKey)d*=2;dolly(d,e.clientX,e.clientY);},{passive:false});
window.addEventListener('keydown',e=>{if(document.body.classList.contains('card-revealed'))return;if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||document.querySelector('dialog[open]'))return;const k=e.key.toLowerCase();if(k==='escape'){if(state.clean)toggleClean(false);else if(state.flight)finishFlight();else if(companionOpen){companionOpen=false;$('companionCard').hidden=true;}else if(state.topic>=0){state.topic=-1;fillLetter(state.active);}else showWorld(state.mode==='event'?'ai':state.mode==='chapter'?'personal':'overview');}
 else if(k==='h')toggleClean();else if(k==='p'){state.monitor=!state.monitor;$('performance').hidden=!state.monitor;}else if(k==='r')resetCamera();else if(['+','='].includes(k)){e.preventDefault();dolly(-150,undefined,undefined,false);}else if(k==='-'){e.preventDefault();dolly(150,undefined,undefined,false);}else if(e.key==='ArrowRight'){e.preventDefault();state.mode==='event'?navigateAI(Math.min(profile.ai_history.length-1,state.aiEvent+1)):navigate(state.active===profile.chapters.length-1?-1:state.active+1);}else if(e.key==='ArrowLeft'){e.preventDefault();state.mode==='event'?navigateAI(Math.max(0,state.aiEvent-1)):navigate(Math.max(-1,state.active-1));}else if(e.code==='Space'&&e.target===document.body){e.preventDefault();state.orbiting=!state.orbiting;updateNav();}});
function resetCamera(){state.exploring=false;document.body.classList.remove('exploring');state.orbiting=false;animateView(state.mode==='chapter'?targetView(state.active):state.mode==='event'?eventView(state.aiEvent):modeView(state.mode));updateNav();}
function encounter(){if(state.mode!=='overview')showWorld('overview');if(state.mergePlaying){state.mergePlaying=false;state.mergeGoal=state.merge;$('encounterPlay').textContent='▷ 继续';return;}if(state.merge>.96){state.merge=0;state.mergeGoal=0;updateWorld();}state.mergePlaying=true;state.mergeGoal=1;$('encounterPlay').textContent='Ⅱ 暂停';state.exploring=false;document.body.classList.remove('exploring');}
$('meetHero').onclick=$('encounterPlay').onclick=encounter;$('encounterRange').oninput=e=>{state.mergePlaying=false;state.mergeGoal=Number(e.target.value)/100;if(state.mode!=='overview')showWorld('overview');$('encounterPlay').textContent='▷ 相遇';};
$('home').onclick=$('navMap').onclick=$('overviewBtn').onclick=()=>showWorld('overview');$('navPersonal').onclick=$('humanGalaxyTitle').onclick=()=>showWorld('personal');$('navAI').onclick=$('footerAI').onclick=$('aiGalaxyTitle').onclick=$('readerAI').onclick=$('companionExplore').onclick=()=>showWorld('ai');$('aiArchive').onclick=openAIHistory;$('begin').onclick=()=>navigate(0);
$('zoomIn').onclick=()=>dolly(-180,undefined,undefined,false);$('zoomOut').onclick=()=>dolly(180,undefined,undefined,false);$('resetView').onclick=resetCamera;$('orbitToggle').onclick=()=>{if(!interruptCamera())return;state.orbiting=true;$('orbitToggle').setAttribute('aria-pressed','true');};
$('orbitToggle').onclick=()=>{const old=state.orbiting;if(!interruptCamera())return;state.orbiting=!old;updateNav();};$('helpButton').onclick=()=>$('helpDialog').showModal();$('eventClose').onclick=()=>showWorld('ai');$('prevEvent').onclick=()=>navigateAI(state.aiEvent-1);$('nextEvent').onclick=()=>navigateAI(state.aiEvent+1);$('companionLabel').onclick=showCompanion;$('companionClose').onclick=()=>{companionOpen=false;$('companionCard').hidden=true;};
